var sec = tree.root.get_node("Main/HUD_Right/VBoxContainer/CommandScrollContainer/CommandPanel/ObjectivesSection")
for c in sec.get_children():
	if c is Label and c.text.begins_with("NML_1"):
		return c.text
return ""

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sw11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
